\title{Tropical Dequantization and Decision Stability\\in Max-Affine Neural Networks}
\author{Aristotle}
\date{July 19, 2026}

\begin{document}
\maketitle

\begin{abstract}
Max-affine expressions form the convex piecewise-linear sector of rectified neural computation and, simultaneously, finite binary tropical polynomials with affine leaves. We compare their tropical evaluation with the smooth evaluation obtained by replacing every binary maximum with log-sum-exp. For an expression of depth $d$ and inverse temperature $\beta>0$, the smooth value lies above the tropical value by at most $d\log(2)/\beta$, uniformly over the input space. Binary classification is consequently unchanged whenever the tropical score has absolute value greater than this error. We also solve the recurrence underlying the budget $2^L\prod_iw_i$ while distinguishing that algebraic identity from a universal region theorem. Finally, scalar ReLU gives two minimal obstructions to broader claims: its zero set contains an open half-line, and it has a width-one kink although $\binom12=0$. The results identify a precise tropical-to-analytic bridge and delimit the hypotheses needed for geometric extensions.
\end{abstract}

\section{Introduction}
A scalar classifier assigns a score $F(x)$ and places its decision threshold at zero. For rectified linear networks, the score is piecewise affine, which suggests a connection to tropical and polyhedral geometry. Several claims must nevertheless be separated: whether the score itself is tropical, whether its raw zero set is a hypersurface, whether widths determine regions or singularities, and whether smooth approximations preserve labels or topology.

This paper isolates the setting where the tropical description is exact. A max-affine expression is a binary tree with affine leaves and maximum at internal nodes. It describes a convex piecewise-affine upper envelope and includes the operation $\ReLU(t)=\max(0,t)$. We replace every maximum by
\[
\LSE_\beta(a,b)=\frac1\beta\log(e^{\beta a}+e^{\beta b}),\qquad \beta>0.
\]
The resulting smooth value differs from the hard value by at most $d\log(2)/\beta$, where $d$ is the deepest chain of maxima. The dependence is on depth, not the total number of leaves.

This yields a label certificate outside an explicit uncertainty band. It does not, by itself, imply topological equivalence of zero sets. We also distinguish a solved layerwise recurrence from the unproved geometric premise that such a recurrence counts realized regions. Elementary counterexamples then show that unrestricted ReLU zero sets need not be hypersurfaces and pair-count formulas need not detect kinks.

\section{Max-affine expressions}
Let $X$ be a set, usually $\mathbb R^n$.

\begin{definition}[Max-affine expression]
A max-affine expression is recursively either an affine leaf $g:X\to\mathbb R$ or an expression $\max(P,Q)$ formed from two max-affine expressions. On $\mathbb R^n$, an affine leaf has the form $g(x)=a\cdot x+b$.
\end{definition}

\begin{definition}[Tropical evaluation]
The tropical evaluation $F_P$ is defined by
\[
F_g(x)=g(x),\qquad F_{\max(P,Q)}(x)=\max(F_P(x),F_Q(x)).
\]
\end{definition}

Thus $F_P$ is the upper envelope of its affine leaves. If the leaves are affine, it is convex and piecewise affine. Ties between active leaves form its tropical corner locus, which is conceptually distinct from the threshold set $\{x:F_P(x)=0\}$.

\begin{definition}[Depth]
The depth is
\[
d(g)=0,\qquad d(\max(P,Q))=1+\max(d(P),d(Q)).
\]
It counts maximum nodes on a deepest root-to-leaf path.
\end{definition}

\begin{definition}[Rectification]
For an expression $P$, define $\ReLU(P)=\max(0,P)$, where $0$ is the constant zero affine function.
\end{definition}

\begin{proposition}[Exact rectified evaluation]
For every $x\in X$,
\[
F_{\ReLU(P)}(x)=\max(0,F_P(x)).
\]
\end{proposition}
\begin{proof}
This follows directly from the recursive evaluation rule at the newly introduced maximum node.
\end{proof}

\section{Log-sum-exp dequantization}
\begin{definition}[Smooth evaluation]
For $\beta>0$, define
\[
S_{g,\beta}(x)=g(x)
\]
and
\[
S_{\max(P,Q),\beta}(x)=\frac1\beta\log\left(e^{\beta S_{P,\beta}(x)}+e^{\beta S_{Q,\beta}(x)}\right).
\]
The parameter $\beta$ is inverse temperature.
\end{definition}

\begin{lemma}[Binary log-sum-exp estimate]\label{lem:lse}
For $a,b\in\mathbb R$ and $\beta>0$,
\[
\max(a,b)\leq \LSE_\beta(a,b)\leq \max(a,b)+\frac{\log2}{\beta}.
\]
\end{lemma}
\begin{proof}
Let $m=\max(a,b)$. Factoring $e^{\beta m}$ gives
\[
\LSE_\beta(a,b)=m+\frac1\beta\log\left(e^{\beta(a-m)}+e^{\beta(b-m)}\right).
\]
At least one summand in parentheses is $1$, and each is at most $1$. The logarithmic correction therefore lies between $0$ and $\log2/\beta$.
\end{proof}

\begin{lemma}[One-sided domination]\label{lem:dom}
For every $P$, $x$, and $\beta>0$,
\[
F_P(x)\leq S_{P,\beta}(x).
\]
\end{lemma}
\begin{proof}
Use structural induction. Equality holds at leaves. At a maximum node, apply the induction hypotheses, monotonicity, and the lower bound in Lemma~\ref{lem:lse}.
\end{proof}

\begin{theorem}[Depth-controlled upper approximation]\label{thm:upper}
For every max-affine expression $P$, every $x\in X$, and $\beta>0$,
\[
S_{P,\beta}(x)\leq F_P(x)+\frac{d(P)\log2}{\beta}.
\]
\end{theorem}
\begin{proof}
Induct on $P$. At a leaf the two evaluations agree and the depth is zero. Suppose $P=\max(Q,R)$ and let $D=\max(d(Q),d(R))$. The induction hypotheses bound each smooth child by its hard value plus $D\log2/\beta$. Translation equivariance and monotonicity of log-sum-exp therefore give
\[
S_{P,\beta}(x)
\leq \LSE_\beta(F_Q(x),F_R(x))+\frac{D\log2}{\beta}.
\]
Lemma~\ref{lem:lse} contributes one additional $\log2/\beta$ and replaces the binary log-sum-exp by the maximum of the hard child values. Since $d(P)=D+1$, the result follows.
\end{proof}

\begin{theorem}[Two-sided dequantization error]\label{thm:error}
If $P$ has depth $d$, then for every $x\in X$ and $\beta>0$,
\[
0\leq S_{P,\beta}(x)-F_P(x)\leq\frac{d\log2}{\beta}.
\]
\end{theorem}
\begin{proof}
Combine Lemma~\ref{lem:dom} and Theorem~\ref{thm:upper}.
\end{proof}

The estimate is uniform in the input and independent of input dimension, affine coefficients, and leaf count. A balanced tree with $N$ leaves may have depth of order $\log_2N$, while a chain may have depth of order $N$.

\begin{corollary}[Uniform soft-ReLU estimate]
For $x\in\mathbb R$ and $\beta>0$,
\[
\max(0,x)\leq\frac1\beta\log(1+e^{\beta x})
\leq\max(0,x)+\frac{\log2}{\beta}.
\]
\end{corollary}
\begin{proof}
Apply Lemma~\ref{lem:lse} to $0$ and $x$.
\end{proof}

At a binary tie $a=b$, the local error equals $\log2/\beta$, so the one-node constant is sharp. Representation also matters: hard maximum is associative and idempotent, while smoothing records multiplicity. Balancing an expression can improve its depth-based certificate.

\section{Classification stability}
Define the hard label to be positive precisely when $F_P(x)>0$, and define the smooth label analogously using $S_{P,\beta}$.

\begin{theorem}[Margin stability]\label{thm:margin}
Let $P$ have depth $d$. If $\beta>0$ and
\[
\frac{d\log2}{\beta}<|F_P(x)|,
\]
then
\[
S_{P,\beta}(x)>0\quad\Longleftrightarrow\quad F_P(x)>0.
\]
\end{theorem}
\begin{proof}
If $F_P(x)>0$, Lemma~\ref{lem:dom} makes the smooth value positive. If $F_P(x)<0$, the margin assumption gives $F_P(x)+d\log2/\beta<0$, and Theorem~\ref{thm:upper} makes the smooth value negative. The strict margin excludes a zero hard score.
\end{proof}

\begin{corollary}[Temperature from margin]
If $|F_P(x)|\geq m>0$ on $A\subseteq X$, then labels agree throughout $A$ whenever
\[
\beta>\frac{d\log2}{m}.
\]
\end{corollary}

This is a label theorem, not a topological theorem. Uniformly close functions can have non-isotopic zero sets if critical behavior occurs near zero. A critical-value exclusion or transversality assumption is needed to control topology.

\section{The layerwise budget identity}
For a finite width sequence, set
\[
R([])=1,
\qquad
R([w_1,\ldots,w_L])=2w_1R([w_2,\ldots,w_L]).
\]

\begin{theorem}[Closed form of the proposed recurrence]
For all nonnegative integer widths,
\[
R([w_1,\ldots,w_L])=2^L\prod_{i=1}^Lw_i.
\]
\end{theorem}
\begin{proof}
Induct on the sequence. The empty case is the empty product identity. In the nonempty case, substitute the induction hypothesis:
\[
R=2w_1\left(2^{L-1}\prod_{i=2}^Lw_i\right)
=2^L\prod_{i=1}^Lw_i.
\]
\end{proof}

This theorem solves the recurrence; it does not prove that the recurrence universally counts realized regions. Actual cuts depend on dimension, arrangement rank, coincident hyperplanes, inactive units, and bottlenecks. A geometric recurrence must justify its local cutting factor.

\section{Obstructions to unrestricted claims}
\subsection{A zero set with interior}
Let $r(x)=\max(0,x)$.

\begin{theorem}[Interior in the ReLU zero set]
The negative open half-line satisfies
\[
(-\infty,0)\subseteq\{x\in\mathbb R:r(x)=0\}.
\]
In fact, the complete zero set is $(-\infty,0]$.
\end{theorem}
\begin{proof}
For $x<0$, the larger of $0$ and $x$ is $0$. The same holds at zero, while $r(x)=x>0$ for $x>0$.
\end{proof}

Thus an arbitrary ReLU score's raw zero set need not be a codimension-one hypersurface. One may instead study the boundary of a strict label region or impose a sign-changing regularity condition.

\subsection{A pair count that misses a kink}
\begin{theorem}[Width-one singularity obstruction]
Although $\binom12=0$, for every $\varepsilon>0$,
\[
r(-\varepsilon)=0,
\qquad
r(\varepsilon)=\varepsilon.
\]
Consequently $r$ has distinct one-sided slopes at zero.
\end{theorem}
\begin{proof}
The evaluations follow from the sign of $\varepsilon$. The function is constant on the negative side and the identity on the positive side, so its one-sided slopes are $0$ and $1$.
\end{proof}

An unguarded product of layerwise pair counts can therefore vanish despite genuine nonsmooth behavior. Singularities should instead be associated with realized active pieces and their incidence.

\section{Algorithms and applications}
A postorder traversal evaluates both tropical and smooth expressions. At leaves it computes $a\cdot x+b$; at internal nodes it computes either a maximum or the stable formula
\[
m+\frac1\beta\log\left(e^{\beta(a-m)}+e^{\beta(b-m)}\right),
\qquad m=\max(a,b).
\]
For a tree with $N$ nodes and input dimension $n$, direct evaluation costs $O(Nn)$ including leaf dot products and uses $O(d)$ recursion memory.

A stability certifier computes $E=d\log2/\beta$. If $|F_P(x)|>E$, it returns the hard label with the guarantee of Theorem~\ref{thm:margin}; otherwise it returns ``unresolved by this bound.'' The test is sufficient, not necessary.

For two-dimensional visualization, evaluate both scores on a grid and interpolate cell edges across which signs change. An $M\times M$ grid costs $O(M^2N)$ tree operations. Such a plot illustrates contour behavior but does not establish topology, since finite resolution may miss small components.

The estimate calibrates softplus surrogates in differentiable optimization, finite-temperature approximations in energy models, and smoothing in robust classification. It also suggests balancing maximum trees to reduce depth. The counterexamples recommend measuring label interfaces rather than raw zero plateaus and recording active affine ties rather than nominal neuron pairs.

\section{Discussion and future directions}
Signed affine combinations can destroy convex max-affine structure. A natural extension is a representation of a scalar rectified network as a difference of two max-affine expressions. Its decision set would be an equality locus of two tropical polynomials, producing tropical-rational rather than purely tropical geometry.

The margin band suggests a topological conjecture: on a compact domain with no critical value inside a band of width $d\log2/\beta$ around zero, hard and smooth decision sets may be ambient isotopic. The missing ingredient is geometric transversality, not a stronger value estimate.

Singularity bounds should count simultaneous ties among active affine leaves. In $\mathbb R^n$, incidence among active $(n+1)$-subsets is a plausible replacement for layerwise products of pair counts. Region bounds should similarly replace nominal width by the rank of the arrangement induced on each inherited region, using arrangement growth functions to account for bottlenecks. Controlled tropical-rational representations may ultimately connect active-set compression to classification-capacity bounds.

\section{Conclusion}
For max-affine neural expressions, tropical evaluation and log-sum-exp dequantization differ uniformly by a quantity in
\[
\left[0,\frac{d\log2}{\beta}\right].
\]
Outside this explicit score band, binary labels agree. The estimate depends on depth rather than leaf count. The recurrence multiplying by $2w_i$ has closed form $2^L\prod_iw_i$, but geometric use of that budget requires arrangement assumptions. Scalar ReLU shows both that raw zero sets may have interior and that width-one kinks evade pair counts. These distinctions provide a rigorous basis for extending tropical geometry from convex max-affine models to broader neural decision geometry.

\end{document}

